function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
var EST=[],CUR=null,E=window.H3L_ESTR;
function lvl(id,e){var m=E.mat[id];if(!m)return 't';var c=m.charAt(E.orden.indexOf(e));return c==='n'||c==='o'?c:'-'}
function visItem(it){if(!EST.length||it[0]!=='n')return true;var id=NID[it[1]];if(!id||!E.mat[id])return true;return EST.some(function(e){return lvl(id,e)!=='-'})}
function estHash(){return EST.length?'.'+EST.join('-'):''}
function estBar(){
  var h='<div class="estbar" role="group" aria-label="Estrategia de explotación"><span class="estl">Estrategia</span><button class="chip'+(!EST.length?' on':'')+'" data-est="todas" aria-pressed="'+(!EST.length)+'">Todas</button>';
  E.orden.forEach(function(e){h+='<button class="chip'+(EST.indexOf(e)>=0?' on':'')+'" data-est="'+e+'" aria-pressed="'+(EST.indexOf(e)>=0)+'">'+esc(E.estrategias[e].n)+'</button>'});
  h+='<p class="esth">Elegí una o más estrategias para ocultar las herramientas nuevas que no aplican y ver cómo cambia el uso de cada una. Guía de H3L pendiente de validación técnica.</p></div>';
  EST.forEach(function(e){var d=E.estrategias[e];h+='<section class="estp"><h3>'+esc(d.n)+'</h3><p>'+esc(d.desc)+'</p><div class="estcols"><div><b>Qué cambia</b><ul>'+d.cambia.map(function(x){return '<li>'+esc(x)+'</li>'}).join('')+'</ul></div><div><b>Evitar</b><ul>'+d.evitar.map(function(x){return '<li>'+esc(x)+'</li>'}).join('')+'</ul></div></div></section>'});
  return h;
}
function render(id){
  var t=T.filter(function(x){return x.id===id})[0]||T[0];CUR=t.id;
  var counts={c:0,q:0,d:0,a:0,n:0},total=0,n=0;
  t.st.forEach(function(s){s.i.forEach(function(it){if(!visItem(it))return;counts[it[0]]++;total++})});
  var parts=[];
  ['c','q','d','a','n'].forEach(function(k){if(counts[k])parts.push('<b>'+counts[k]+'</b> '+KIND[k].l.toLowerCase()+(counts[k]>1&&k!=='a'&&k!=='n'?'s':''))});
  var html=estBar()+'<div class="head"><h2>'+esc(t.name)+'</h2><div class="counts">'+total+' herramientas en orden de uso: '+parts.join(' · ')+'</div></div>';
  html+='<ul class="legend" aria-label="Tipos de herramienta">';
  ['c','q','d','a','n'].forEach(function(k){html+='<li style="color:var(--k-'+k+')"><span class="dot'+(k==='n'?' n':'')+'"></span><span style="color:var(--muted)">'+KIND[k].l+'</span></li>'});
  html+='</ul><div class="stages">';
  t.st.forEach(function(s,si){
    var S=STAGES[si];
    html+='<section class="stage"><div class="chev"><span class="k">'+S.k+' · '+S.f+'</span><span class="n">'+S.n+'</span></div><p class="goal">'+esc(s.g)+'</p><ol class="items" style="list-style:none">';
    var vis=s.i.filter(visItem);if(!vis.length)html+='<li class="item"><span class="num">–</span><div><div class="note">Sin herramientas nuevas específicas de esta estrategia en esta etapa; usá las de la plataforma.</div></div></li>';
    vis.forEach(function(it){
      n++;
      var kd=KIND[it[0]];
      var nm=it[0]==='n'?(NID[it[1]]?'<a href="'+NEW+NID[it[1]]+estHash()+'" target="_blank" rel="noopener">'+esc(it[1])+'</a>':esc(it[1])):'<a href="'+BASE+kd.go+'" target="_blank" rel="noopener">'+esc(it[1])+'</a>';
      var extra='',bd='';
      if(it[0]==='n'&&EST.length&&NID[it[1]]){var id2=NID[it[1]];EST.forEach(function(e){var l=lvl(id2,e),nt=(E.notas[id2]||{})[e];if(l==='n'||l==='o')bd+='<span class="lv '+l+'">'+esc(E.estrategias[e].n)+(l==='o'?' · con ajustes':'')+'</span>';if(nt)extra+='<div class="enote"><b>'+esc(E.estrategias[e].n)+':</b> '+esc(nt)+'</div>'})}
      html+='<li class="item'+(it[0]==='n'?' n':'')+'"><span class="num">'+n+'</span><div><div class="name">'+nm+'</div><div class="note">'+esc(it[2])+'</div><span class="tag '+it[0]+'">'+kd.l+'</span>'+bd+extra+'</div></li>';
    });
    html+='</ol><div class="out"><div class="l">Entregable</div><p>'+esc(s.o)+'</p></div></section>';
  });
  html+='</div><div class="final"><span class="l">Entregable final</span><span class="t">'+esc(t.final)+'</span></div>';
  document.getElementById('panel').innerHTML=html;
  var btns=document.querySelectorAll('#topics button');
  for(var i=0;i<btns.length;i++){btns[i].setAttribute('aria-selected',btns[i].getAttribute('data-id')===t.id?'true':'false')}
  try{history.replaceState(null,'','#'+t.id+estHash())}catch(e){}
}
(function(){
  var ul=document.getElementById('topics'),h='';
  T.forEach(function(t){h+='<li role="presentation"><button role="tab" data-id="'+t.id+'" aria-selected="false">'+esc(t.name)+'</button></li>'});
  ul.innerHTML=h;
  ul.addEventListener('click',function(e){var b=e.target.closest('button');if(b)render(b.getAttribute('data-id'))});
  document.getElementById('panel').addEventListener('click',function(e){var b=e.target.closest('[data-est]');if(!b)return;var v=b.getAttribute('data-est');if(v==='todas')EST=[];else{var i=EST.indexOf(v);if(i>=0)EST.splice(i,1);else EST.push(v);EST.sort(function(a,c){return E.orden.indexOf(a)-E.orden.indexOf(c)})}render(CUR)});
  var hp=(location.hash||'').replace('#','').split('.');
  if(hp[1])EST=hp[1].split('-').filter(function(x){return E.orden.indexOf(x)>=0});
  render(hp[0]||T[0].id);
})();
